css:
@import url("https://fonts.googleapis.com/css2?family=Chango&family=Nunito:wght@400;600;800&display=swap");
:root{--sk:#7BDFF2;--sk2:#DDF6FB;--pk:#F7AEF8;--ink:#22223B;--gr:#4A4E69;--h:"Chango",Impact,sans-serif;--b:"Nunito",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:18px;line-height:1.6;color:var(--ink);background:var(--sk2);min-height:100vh}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2{font-family:var(--h);font-weight:400;margin:0;line-height:1}
.wrap{max-width:1080px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--pk);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--ink);outline-offset:3px}
.nav{display:flex;justify-content:space-between;align-items:center;height:76px;position:relative}.logo{font-weight:800;font-size:22px;text-decoration:none;display:flex;gap:8px;align-items:center}
.menu{display:flex;gap:22px;list-style:none;margin:0;padding:0;font-weight:600}.menu a{text-decoration:none}.menu a:hover{text-decoration:underline}
.burger{display:none;background:none;border:2px solid var(--ink);width:44px;height:40px;border-radius:12px;font-size:20px;cursor:pointer}
.main{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;padding:30px 0 60px}
.big{font-family:var(--h);font-size:clamp(90px,16vw,200px);line-height:.9;color:var(--ink);display:flex;align-items:center}.big i{display:inline-block;width:.8em;height:.8em;border-radius:50%;background:var(--pk);box-shadow:inset -.14em -.1em 0 rgba(34,34,59,.18);margin:0 .02em}
h1{font-size:clamp(28px,3.4vw,40px);margin:16px 0 10px}.lead{font-size:20px;color:var(--gr);margin:0 0 24px;max-width:28em}
.sr{position:relative;margin-bottom:14px}.sr input{width:100%;font:18px var(--b);padding:16px 20px 16px 50px;border:3px solid var(--ink);border-radius:40px;background:#fff}.sr svg{position:absolute;left:18px;top:50%;transform:translateY(-50%)}
.links{list-style:none;padding:0;margin:0;display:grid;gap:8px}.links a{display:flex;justify-content:space-between;align-items:center;background:#fff;border-radius:16px;padding:12px 18px;text-decoration:none;font-weight:600;border:2px solid transparent}.links a:hover{border-color:var(--ink)}.links small{font-weight:400;color:var(--gr)}
.none{background:#fff;border-radius:16px;padding:14px 18px;color:var(--gr)}
.btn{display:inline-block;background:var(--ink);color:#fff;text-decoration:none;font:800 17px var(--b);padding:13px 24px;border-radius:40px;border:0;cursor:pointer;margin-top:18px}
.ill svg{width:100%;height:auto;max-width:460px;margin:0 auto;display:block}
.float{animation:fl 4s ease-in-out infinite;transform-origin:center}@keyframes fl{50%{transform:translateY(-12px) rotate(-3deg)}}
.pick{background:var(--ink);color:#fff;border-radius:24px;padding:20px 22px;margin-top:10px;display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}.pick b{color:var(--pk)}.pick button{font:800 15px var(--b);background:var(--pk);border:0;border-radius:30px;padding:9px 16px;cursor:pointer;color:var(--ink)}
footer{padding:22px 0;font-size:15px;color:var(--gr)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:860px){.main{grid-template-columns:1fr}.ill{order:-1}.ill svg{max-width:280px}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:76px;left:0;right:0;background:#fff;flex-direction:column;padding:18px 22px;z-index:30;border-radius:0 0 18px 18px}.menu.open{display:flex}}
@media (prefers-reduced-motion:reduce){.float{animation:none}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const L=[["New books this week","Fiction, cookbooks and more"],["Gift cards","From £10, sent by email"],["Events and author talks","Book club every Thursday"],["Delivery and returns","Free UK delivery over £25"],["Children's books","Picture books to teen reads"],["Order a book we don't stock","Usually here in 3 days"],["Opening hours and directions","Open 7 days"],["Contact us","We reply within a day"]];
function draw(){const q=$('q').value.trim().toLowerCase();const r=L.filter(l=>!q||(l[0]+' '+l[1]).toLowerCase().includes(q));$('links').innerHTML=r.length?r.slice(0,q?8:4).map(l=>`<li><a href="#">${l[0]} <small>${l[1]}</small></a></li>`).join(''):'<li class="none">Nothing matches that. Try "gift" or "events", or email hello@papermoon.example.</li>'}
$('q').addEventListener('input',draw);draw();
const B=["a quiet novel about a lighthouse keeper","a cookbook for one-pan dinners","a guide to birds you can see from your window","a short, funny memoir about moving to the sea","a picture book about a very brave snail"];let bi=0;const pick=()=>{$('bk').textContent=B[bi];bi=(bi+1)%B.length};$('nb').onclick=pick;pick();
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
